/**
 * 統合リストのインデックスから、指定ウィンドウが実際に読み書きすべきファイル名を解決する。
 * Dir A と Dir B でファイル名が異なる（例: 0001.tga / 0001_r.tga）ケースがあるため、
 * 代表ファイル名ではなくフレーム番号マッピングを正としてサイド別に引く。
 * フレームは存在するがそのサイドにファイルが無い場合は null を返す。
 */
export function resolveFileNameForSide(
  index: number,
  side: 'A' | 'B',
  mergedFrameNumbers: string[],
  mergedFrameMap: Map<string, MergedFrameMapItem>,
  unifiedFileList: string[]
): string | null {
  const frameNum = mergedFrameNumbers[index];
  if (frameNum) {
    const item = mergedFrameMap.get(frameNum);
    if (item) {
      return (side === 'A' ? item.fileNameA : item.fileNameB) ?? null;
    }
  }
  return unifiedFileList[index] ?? null;
}

