113	// ファイル名から「4桁等の連番数字」を抽出する関数 (例: b_go0003.tga -> "0003", a0012.tga -> "0012")
114	export function extractFrameNumber(fileName: string): string {
115	  const match = fileName.match(/(?:^|[^0-9])([0-9]{2,4})(?=[^0-9]*\.[a-z0-9]+$)/i);
116	  if (match) return match[1];
117	  const numMatch = fileName.match(/([0-9]+)(?=[^0-9]*\.[a-z0-9]+$)/i);
118	  return numMatch ? numMatch[1].padStart(4, '0') : fileName;
119	}
120	
121	// サブフォルダAとサブフォルダBのファイル群から異名連番マージマップを再構築する関数
122	export function buildMergedFrameData(
123	  listA: string[],
124	  listB: string[]
125	): { frameNumbers: string[]; frameMap: Map<string, MergedFrameMapItem>; unifiedFiles: string[] } {
126	  const frameMap = new Map<string, MergedFrameMapItem>();
127	
128	  listA.forEach((f) => {
129	    const num = extractFrameNumber(f);
130	    const item = frameMap.get(num) || { frameNumber: num };
131	    item.fileNameA = f;
132	    frameMap.set(num, item);
133	  });
134	
135	  listB.forEach((f) => {
136	    const num = extractFrameNumber(f);
137	    const item = frameMap.get(num) || { frameNumber: num };
138	    item.fileNameB = f;
139	    frameMap.set(num, item);
140	  });
141	
142	  const frameNumbers = Array.from(frameMap.keys()).sort((a, b) => {
143	    const numA = parseInt(a, 10);
144	    const numB = parseInt(b, 10);
145	    if (!isNaN(numA) && !isNaN(numB)) return numA - numB;
146	    return a.localeCompare(b);
147	  });
148	
149	  const unifiedFiles: string[] = [];
150	  frameNumbers.forEach((num) => {
151	    const item = frameMap.get(num)!;
152	    const representative = item.fileNameA || item.fileNameB || num;
153	    unifiedFiles.push(representative);
154	  });
155	
156	  return { frameNumbers, frameMap, unifiedFiles };
157	}
158	
159	/**
160	 * 統合リストのインデックスから、指定ウィンドウが実際に読み書きすべきファイル名を解決する。
161	 * Dir A と Dir B でファイル名が異なる（例: 0001.tga / 0001_r.tga）ケースがあるため、
162	 * 代表ファイル名ではなくフレーム番号マッピングを正としてサイド別に引く。
163	 * フレームは存在するがそのサイドにファイルが無い場合は null を返す。
164	 */
165	export function resolveFileNameForSide(
166	  index: number,
167	  side: 'A' | 'B',
168	  mergedFrameNumbers: string[],
169	  mergedFrameMap: Map<string, MergedFrameMapItem>,
170	  unifiedFileList: string[]
171	): string | null {
172	  const frameNum = mergedFrameNumbers[index];
173	  if (frameNum) {
174	    const item = mergedFrameMap.get(frameNum);
175	    if (item) {
176	      return (side === 'A' ? item.fileNameA : item.fileNameB) ?? null;
177	    }
178	  }
179	  return unifiedFileList[index] ?? null;
180	}
