/**
 * Kingfisher グローバルストア (Zustand)。
 *
 * 状態と操作は責務ごとに store/slices/* へ分割してある。
 * このファイルはそれらを 1 つのストアへ合成するだけの薄い層。
 * 各スライスは共通の get を通じて他スライスの値・アクションを参照できる。
 *
 * 型は store/types.ts に集約し、既存の import 互換のためここから再輸出する。
 */

import { create } from 'zustand';
import { PaintStore } from './types';
import { createUiSlice } from './slices/uiSlice';
import { createViewSlice } from './slices/viewSlice';
import { createWindowSlice } from './slices/windowSlice';
import { createFileSlice } from './slices/fileSlice';
import { createDocumentSlice } from './slices/documentSlice';
import { createToolSlice } from './slices/toolSlice';
import { createEditSlice } from './slices/editSlice';
import { createLightTableSlice } from './slices/lightTableSlice';

export const usePaintStore = create<PaintStore>()((...a) => ({
  ...createUiSlice(...a),
  ...createViewSlice(...a),
  ...createWindowSlice(...a),
  ...createFileSlice(...a),
  ...createDocumentSlice(...a),
  ...createToolSlice(...a),
  ...createEditSlice(...a),
  ...createLightTableSlice(...a),
}));

export * from './types';
=== imageDecode.ts ===
/**
 * 画像ファイルの読み込み・複製まわりの共通処理。
 *
 * Kingfisher は .tga を主素材としつつ、タイムシートや指示メモの .png / .jpg も
 * 「閲覧専用」として同じパイプラインに載せる。その差異をここに閉じ込める。
 */

import { decodeTGA, TGAImage } from './tga';

/** 画像ファイルが Kingfisher の編集対象 (TGA) かどうか */
export function isTgaFile(fileName: string): boolean {
  return fileName.toLowerCase().endsWith('.tga');
}

/**
 * キャッシュされた画像は「読み込んだままの原本」として保持する。
 * 編集対象に渡すときは必ずこれで複製し、キャッシュ側が塗りで汚れないようにする。
 */
export function cloneTGAImage(image: TGAImage): TGAImage {
  return { ...image, data: new Uint8ClampedArray(image.data) };
}

/** PNG / JPEG を Canvas 経由で RGBA 配列へ変換する (閲覧専用扱い) */
function decodeRasterImageFile(file: File): Promise<TGAImage> {
  return new Promise((resolve, reject) => {
    const img = new Image();
    const url = URL.createObjectURL(file);

    img.onload = () => {
      URL.revokeObjectURL(url);
      const canvas = document.createElement('canvas');
      canvas.width = img.width;
      canvas.height = img.height;
      const ctx = canvas.getContext('2d');
      if (!ctx) {
        reject(new Error('Canvas context error'));
        return;
      }
      ctx.drawImage(img, 0, 0);
      const imgData = ctx.getImageData(0, 0, img.width, img.height);
      resolve({
        width: img.width,
        height: img.height,
        pixelDepth: 32,
        data: imgData.data,
        isReadOnly: true,
      });
    };

    img.onerror = (err) => {
      URL.revokeObjectURL(url);
      reject(err);
    };

    img.src = url;
  });
}

/**
 * 拡張子を問わず 1 枚の画像ファイルをデコードする。
 * decodeTga を渡すと TGA のデコードだけを差し替えられる (Web Worker 版を注入する用途)。
 */
export async function decodeAnyImageFile(
  file: File,
  decodeTga: (buffer: ArrayBuffer) => Promise<TGAImage> | TGAImage = decodeTGA
): Promise<TGAImage> {
  if (isTgaFile(file.name)) {
    const buffer = await file.arrayBuffer();
    return decodeTga(buffer);
  }
  return decodeRasterImageFile(file);
}

/** キャンバス背景の市松模様パターン */
export function createCheckerPattern(
  ctx: CanvasRenderingContext2D,
  size: number = 8
): CanvasPattern | null {
  const patternCanvas = document.createElement('canvas');
  patternCanvas.width = size * 2;
  patternCanvas.height = size * 2;
  const pCtx = patternCanvas.getContext('2d');
  if (!pCtx) return null;

  pCtx.fillStyle = '#FFFFFF';
  pCtx.fillRect(0, 0, size * 2, size * 2);
  pCtx.fillStyle = '#CBD5E1';
  pCtx.fillRect(0, 0, size, size);
  pCtx.fillRect(size, size, size, size);

  return ctx.createPattern(patternCanvas, 'repeat');
}

