        const dockRect = dockRectCache.get(dockTargetId);
        const isOver = !!dockRect && isPointerOverRect(dockRect, ev.clientX, ev.clientY);
        if (!isOver) hasLeftDockTarget = true;
        setIsOverDockTarget(hasLeftDockTarget && isOver);
      };

