  const bringToFront = useCallback(() => {
    if (isFloating) bringWindowToFront(id);
  }, [isFloating, bringWindowToFront, id]);

  return {
    targetRef,
    windowStyle,
    handleHeaderPointerDown,
    getResizeHandler,
    isOverDockTarget,
    bringToFront,
  };
}

