        splitFileIndex: 0,
      });
    },"""
assert old in s
s=s.replace(old, """        currentFileIndex: firstIndexWithFile(frameNumbers, frameMap, 0),
        splitFileIndex: firstIndexWithFile(frameNumbers, frameMap, 1),
      });
    },""",1)

def patch_action(src, action_name, changed_view):
    """片側を差し替えるアクションのインデックス算出を差し込む"""
    marker = f"  {action_name}: "
    i = src.index(marker)
    # 直後の return { ... }; を探す
    r = src.index("      return {", i)
    keep = 1 - changed_view
    changed_key = 'splitFileIndex' if changed_view == 1 else 'currentFileIndex'
    keep_key = 'splitFileIndex' if keep == 1 else 'currentFileIndex'
    keep_prev = 'state.splitFileIndex' if keep == 1 else 'state.currentFileIndex'
    inject = (
        f"      const {changed_key} = firstIndexWithFile(frameNumbers, frameMap, {changed_view});\n"
        f"      const {keep_key} = keepFrameIndex(\n"
        f"        state.mergedFrameNumbers,\n"
        f"        {keep_prev},\n"
        f"        frameNumbers,\n"
        f"        frameMap,\n"
        f"        {keep}\n"
        f"      );\n"
    )
    src = src[:r] + inject + src[r:]
    # return 内のインデックス指定を差し替える
    end = src.index("      };", r)
    body = src[r:end]
    body = body.replace("        currentFileIndex: 0,\n", "        currentFileIndex,\n")
    body = body.replace("        splitFileIndex: 0,\n", "        splitFileIndex,\n")
    if "currentFileIndex" not in body:
        body = body.rstrip() + "\n        currentFileIndex,\n"
    if "splitFileIndex" not in body:
        body = body.rstrip() + "\n        splitFileIndex,\n"
    return src[:r] + body + src[end:]

for name, view in [
    ('setSelectedSubDirA', 0),
    ('setSelectedSubDirB', 1),
    ('setCustomDropFolderA', 0),
    ('setCustomDropFolderB', 1),
    ('setFolderHandleA', 0),
    ('setFolderHandleB', 1),
    ('setFolderFilesA', 0),
    ('setFolderFilesB', 1),
]:
    s = patch_action(s, name, view)

io.open(p,'w',encoding='utf-8').write(s)
print("ok")
