import { describe, it, expect } from 'vitest';
import { resolveFileHandle } from './fileSystemPath';
import { usePaintStore } from '../store/usePaintStore';

function makeDir(name: string, children: Record<string, any>): any {
  return {
    name,
    getDirectoryHandle: async (n: string) => {
      const c = children[n];
      if (!c || !c.getFileHandle) throw new Error(`NotFoundError: no dir "${n}" in "${name}"`);
      return c;
    },
    getFileHandle: async (n: string) => {
      const c = children[n];
      if (!c || c.getFileHandle) throw new Error(`NotFoundError: no file "${n}" in "${name}"`);
      return c;
    },
  };
}

const cel = { kind: 'file' };
const goDir = makeDir('_go', { 'A0001.tga': cel });
const rootDir = makeDir('Cat', { _go: goDir });

