42	 * 4 種すべて)、同じフォルダでも開き方によって .png が見えたり見えなかったりした。
43	 */
44	export const SUPPORTED_IMAGE_PATTERN = /\.(tga|png|jpe?g)$/i;
45	
46	export function isSupportedImageFile(fileName: string): boolean {
